import 'dart:typed_data';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';

Future<Map<String, int>> _bbox(WidgetTester tester, Key key) async {
  final element = tester.element(find.byKey(key));
  final renderObject = element.renderObject! as RenderRepaintBoundary;
  final image = await renderObject.toImage(pixelRatio: 1.0);
  final byteData = await image.toByteData(format: ui.ImageByteFormat.rawRgba);
  final bytes = byteData!.buffer.asUint8List();
  final w = image.width, h = image.height;
  int minX = w, minY = h, maxX = -1, maxY = -1;
  for (var y = 0; y < h; y++) {
    for (var x = 0; x < w; x++) {
      final i = (y * w + x) * 4;
      final a = bytes[i + 3];
      // background is opaque white; count any non-white, non-transparent pixel as "ink"
      final r = bytes[i], g = bytes[i + 1], b = bytes[i + 2];
      final isBackground = a == 0 || (r > 250 && g > 250 && b > 250);
      if (!isBackground) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
      }
    }
  }
  return {
    'w': w,
    'h': h,
    'minX': minX,
    'minY': minY,
    'maxX': maxX,
    'maxY': maxY,
    'inkW': maxX - minX + 1,
    'inkH': maxY - minY + 1,
  };
}

void main() {
  testWidgets('measure icon vs spinner footprint', (tester) async {
    const boxSize = 32.0;
    await tester.pumpWidget(
      MaterialApp(
        home: Material(
          color: Colors.white,
          child: Center(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                RepaintBoundary(
                  key: const Key('icon'),
                  child: const SizedBox(
                    width: boxSize,
                    height: boxSize,
                    child: Icon(
                      Icons.check_circle_outline,
                      size: boxSize,
                      color: Colors.black,
                    ),
                  ),
                ),
                RepaintBoundary(
                  key: const Key('spinner'),
                  child: const SizedBox(
                    width: boxSize,
                    height: boxSize,
